SELECT subscription_id
FROM subscriptions
WHERE status = 'active';

SELECT DISTINCT ON (s.account_id) s.account_id, s.plan_id
FROM subscriptions AS s
ORDER BY s.account_id, s.starts_on DESC, s.subscription_id DESC;

SELECT invoice_id, MAX(attempted_at) AS latest_dunning_attempt_at
FROM dunning_attempts
GROUP BY invoice_id;

SELECT delivery_id
FROM delivery_events
WHERE (payload #>> '{temperature_c}')::NUMERIC >= 7;

SELECT alert_id
FROM alerts
WHERE status = 'open';

SELECT alert_id
FROM alerts
WHERE status = 'open';

SELECT customer_id, COUNT(alert_id) FILTER (WHERE status = 'open') AS open_alert_count
FROM alerts
GROUP BY customer_id;

SELECT investigation_id, EXTRACT(EPOCH FROM (closed_at - opened_at)) / 3600 AS resolution_hours
FROM investigations
WHERE closed_at IS NOT NULL;

SELECT product_id, on_hand_qty, snapshot_at
FROM (
    SELECT product_id, on_hand_qty, snapshot_at,
           ROW_NUMBER() OVER (
               PARTITION BY product_id
               ORDER BY snapshot_at DESC, snapshot_id DESC
           ) AS rn
    FROM inventory_snapshots
) AS latest
WHERE rn = 1;

SELECT case_id, customer_id, opened_at, outcome, resolved_at
FROM cases
WHERE resolved_at IS NULL;
